<template><div><div class="page-head"><div><span>WUJiaxin Integration / IETM</span><h2>航天器部件档案</h2><p>成员成果中的部件基础信息与寿命档案，共 {{rows.length}} 项。</p></div><el-input v-model="keyword" clearable placeholder="按编号或名称检索" style="width:260px"/></div><div class="cards"><el-card v-for="row in filtered" :key="row.code" shadow="hover" @click="show(row)"><div class="code">{{row.code}}</div><h3>{{row.name}}</h3><p>{{row.manufacturer||'生产单位未填写'}}</p><div><span>已飞行次数</span><b>{{row.flight_count??'—'}}</b></div></el-card></div><el-drawer v-model="open" :title="`${current.name||''} · ${current.code||''}`" size="520px"><el-descriptions :column="1" border><el-descriptions-item v-for="x in detail.base_info" :key="x.baseinfo||x.consumerinfo" :label="x.baseinfo||x.consumerinfo">{{x.attribute??x.attributevalue}}</el-descriptions-item></el-descriptions></el-drawer></div></template>
<script setup>import{ref,computed,onMounted}from'vue';const rows=ref([]),keyword=ref(''),open=ref(false),current=ref({}),detail=ref({base_info:[]});onMounted(async()=>rows.value=(await(await fetch('/api/v1/integrations/wujiaxin/components/')).json()).results||[]);const filtered=computed(()=>{const k=keyword.value.toLowerCase();return rows.value.filter(r=>`${r.code}${r.name}`.toLowerCase().includes(k))});async function show(row){current.value=row;detail.value=await(await fetch(`/api/v1/integrations/wujiaxin/components/${row.code}/`)).json();open.value=true}</script>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.page-head span{font-size:11px;color:#2c82e7;font-weight:700}.page-head h2{margin:7px 0}.page-head p{margin:0;color:#8391a5}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.el-card{border-radius:10px;cursor:pointer}.code{font-size:11px;color:#3788e5;font-weight:700}.el-card h3{margin:10px 0 6px}.el-card p{height:34px;color:#8a97a7;font-size:12px}.el-card div:last-child{border-top:1px solid #edf0f4;padding-top:12px;display:flex;justify-content:space-between;font-size:12px}.el-card b{color:#1f77d5}@media(max-width:1200px){.cards{grid-template-columns:repeat(3,1fr)}}</style>
